{
  "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7918.md",
  "title": "EIP-7918: Blob Base Fee Bounded by Execution Cost",
  "eip_metadata": {
    "eip": 7918,
    "status": "Final",
    "type": "Standards Track",
    "category": "Core",
    "created": "2025-03-25",
    "requires": [4844, 7840],
    "authors": [
      "Anders Elowsson (@anderselowsson)",
      "Ben Adams (@benaadams)",
      "Francesco D'Amato (@fradamt)"
    ]
  },
  "sub_graphs": [
    {
      "id": "SG-001",
      "name": "Reserve Price Parameter Definition",
      "description": "Defines the BLOB_BASE_COST constant that establishes the minimum ratio between blob fees and execution fees. This constant sets the reserve price floor such that a blob must cost at least BLOB_BASE_COST execution gas worth of blob fees, enforcing a ratio of BLOB_BASE_COST / GAS_PER_BLOB (= 1/16) between the reserve blob base fee and the execution base fee.",
      "invariants": [
        {
          "id": "INV-001",
          "text": "The blob base fee will settle at a level where a blob costs at least BLOB_BASE_COST execution gas.",
          "formal": "blob_base_fee >= (BLOB_BASE_COST * base_fee_per_gas) / GAS_PER_BLOB"
        },
        {
          "id": "INV-002",
          "text": "The ratio between the reserve price for the blob base fee and the execution base fee is fixed to BLOB_BASE_COST / GAS_PER_BLOB = 2**13 / 2**17 = 1/16.",
          "formal": "reserve_blob_base_fee / base_fee_per_gas == BLOB_BASE_COST / GAS_PER_BLOB == 1/16"
        },
        {
          "id": "INV-003",
          "text": "The blob fee's share of the total price will always be at least BLOB_BASE_COST / (BLOB_BASE_COST + execution_cost) when the reserve price is active.",
          "formal": "blob_fee_share >= BLOB_BASE_COST / (BLOB_BASE_COST + execution_cost)"
        }
      ],
      "constants": [
        {
          "id": "CONST-001",
          "name": "BLOB_BASE_COST",
          "value": "2**13",
          "value_decimal": 8192,
          "description": "The minimum cost in execution gas units that a blob must effectively cost. Sets the reserve price floor for blob base fees relative to execution costs."
        }
      ],
      "functions": [],
      "state_variables": [],
      "preconditions": [],
      "postconditions": [],
      "dependencies": [
        {
          "id": "DEP-001",
          "eip": 4844,
          "description": "Introduces blob transactions, GAS_PER_BLOB (2**17 = 131072), and the original calc_excess_blob_gas() function that this EIP modifies."
        },
        {
          "id": "DEP-002",
          "eip": 7840,
          "description": "Introduces the blobSchedule configuration for referencing target and max blob counts, as well as baseFeeUpdateFraction."
        }
      ]
    },
    {
      "id": "SG-002",
      "name": "Excess Blob Gas Calculation (Modified)",
      "description": "The core specification change: modifies calc_excess_blob_gas() from EIP-4844 to introduce a reserve price mechanism. When the reserve price (BLOB_BASE_COST * base_fee_per_gas) exceeds the current blob cost (GAS_PER_BLOB * base_fee_per_blob_gas), the function enters the execution-fee-led pricing regime and does not subtract target_blob_gas, causing excess_blob_gas to increase monotonically according to blob_gas_used while capping the per-block maximum increase.",
      "invariants": [
        {
          "id": "INV-004",
          "text": "The per-block maximum increase in excess_blob_gas is unchanged from the original mechanism. In the reserve-price regime, the increase is bounded by blob_gas_used * (max - target) / max.",
          "formal": "max_increase_per_block == GAS_PER_BLOB * blobSchedule.max * (blobSchedule.max - blobSchedule.target) / blobSchedule.max"
        },
        {
          "id": "INV-005",
          "text": "When total blob gas usage (excess + used) is below target, excess_blob_gas resets to 0 regardless of reserve price conditions.",
          "formal": "if (parent.excess_blob_gas + parent.blob_gas_used < target_blob_gas) then excess_blob_gas == 0"
        }
      ],
      "functions": [
        {
          "id": "FN-001",
          "name": "calc_excess_blob_gas",
          "signature": "def calc_excess_blob_gas(parent: Header) -> int",
          "parameters": [
            {
              "name": "parent",
              "type": "Header",
              "description": "The parent block header containing excess_blob_gas, blob_gas_used, and base_fee_per_gas fields."
            }
          ],
          "return_type": "int",
          "description": "Calculates the excess blob gas for the current block based on the parent block's state. Introduces a reserve price check that determines whether to operate in blob-fee-led or execution-fee-led pricing regime.",
          "source_code": "def calc_excess_blob_gas(parent: Header) -> int:\n    target_blob_gas = GAS_PER_BLOB * blobSchedule.target\n    if parent.excess_blob_gas + parent.blob_gas_used < target_blob_gas:\n        return 0\n\n    if BLOB_BASE_COST * parent.base_fee_per_gas > GAS_PER_BLOB * get_base_fee_per_blob_gas(parent):\n        return parent.excess_blob_gas + parent.blob_gas_used * (blobSchedule.max - blobSchedule.target) // blobSchedule.max\n    else:\n        return parent.excess_blob_gas + parent.blob_gas_used - target_blob_gas",
          "ast_summary": {
            "type": "function_definition",
            "name": "calc_excess_blob_gas",
            "parameter_type": "Header",
            "return_type": "int",
            "body_structure": [
              {
                "type": "assignment",
                "target": "target_blob_gas",
                "value": "GAS_PER_BLOB * blobSchedule.target"
              },
              {
                "type": "if_statement",
                "condition": "parent.excess_blob_gas + parent.blob_gas_used < target_blob_gas",
                "consequence": "return 0",
                "label": "under-target check (resets to 0)"
              },
              {
                "type": "if_else_statement",
                "condition": "BLOB_BASE_COST * parent.base_fee_per_gas > GAS_PER_BLOB * get_base_fee_per_blob_gas(parent)",
                "if_branch": "return parent.excess_blob_gas + parent.blob_gas_used * (blobSchedule.max - blobSchedule.target) // blobSchedule.max",
                "else_branch": "return parent.excess_blob_gas + parent.blob_gas_used - target_blob_gas",
                "label": "reserve price check (execution-fee-led vs blob-fee-led regime)"
              }
            ]
          },
          "external_calls": [
            {
              "name": "get_base_fee_per_blob_gas",
              "arguments": ["parent"],
              "description": "Computes the blob base fee from the parent header using fake_exponential() with the current blobSchedule.baseFeeUpdateFraction."
            }
          ]
        }
      ],
      "state_variables": [
        {
          "id": "SV-001",
          "name": "excess_blob_gas",
          "type": "int",
          "location": "Header",
          "description": "Tracks the cumulative excess blob gas across blocks. Used as input to fake_exponential() to determine base_fee_per_blob_gas. Modified by this function each block."
        },
        {
          "id": "SV-002",
          "name": "blob_gas_used",
          "type": "int",
          "location": "Header",
          "description": "The total blob gas consumed in a block. Equal to the number of blobs times GAS_PER_BLOB."
        },
        {
          "id": "SV-003",
          "name": "base_fee_per_gas",
          "type": "int",
          "location": "Header",
          "description": "The execution layer base fee per gas for the block. Used in the reserve price comparison."
        }
      ],
      "preconditions": [
        {
          "id": "PRE-001",
          "text": "The parent header must contain valid excess_blob_gas, blob_gas_used, and base_fee_per_gas fields.",
          "formal": "parent.excess_blob_gas >= 0 AND parent.blob_gas_used >= 0 AND parent.base_fee_per_gas >= 0"
        },
        {
          "id": "PRE-002",
          "text": "The current block's blobSchedule must be used during processing, including the new baseFeeUpdateFraction, max, and target values after a fork.",
          "formal": "blobSchedule == current_fork_blob_schedule"
        }
      ],
      "postconditions": [
        {
          "id": "POST-001",
          "text": "The returned excess_blob_gas is non-negative.",
          "formal": "result >= 0"
        },
        {
          "id": "POST-002",
          "text": "If under target: excess_blob_gas is exactly 0.",
          "formal": "if (parent.excess_blob_gas + parent.blob_gas_used < target_blob_gas) then result == 0"
        },
        {
          "id": "POST-003",
          "text": "In execution-fee-led regime: excess_blob_gas increases without allowing any decrease (no target subtraction).",
          "formal": "if reserve_price_active then result == parent.excess_blob_gas + parent.blob_gas_used * (blobSchedule.max - blobSchedule.target) // blobSchedule.max"
        },
        {
          "id": "POST-004",
          "text": "In blob-fee-led regime: excess_blob_gas follows the original EIP-4844 update rule.",
          "formal": "if NOT reserve_price_active then result == parent.excess_blob_gas + parent.blob_gas_used - target_blob_gas"
        }
      ],
      "state_transitions": [
        {
          "id": "ST-001",
          "name": "Under-Target Reset",
          "description": "When total blob gas (excess + used) is below target, excess resets to 0, effectively resetting the blob fee to its minimum.",
          "trigger": "parent.excess_blob_gas + parent.blob_gas_used < target_blob_gas",
          "from_state": "Any excess_blob_gas state",
          "to_state": "excess_blob_gas = 0"
        },
        {
          "id": "ST-002",
          "name": "Execution-Fee-Led Pricing Regime",
          "description": "When the reserve price exceeds the current blob cost, the function enters execution-fee-led mode. It increases excess_blob_gas proportionally to blob_gas_used without subtracting target_blob_gas, causing the blob fee to rise toward the reserve price floor.",
          "trigger": "BLOB_BASE_COST * parent.base_fee_per_gas > GAS_PER_BLOB * get_base_fee_per_blob_gas(parent)",
          "from_state": "excess_blob_gas where blob fee < reserve price",
          "to_state": "excess_blob_gas += blob_gas_used * (max - target) / max"
        },
        {
          "id": "ST-003",
          "name": "Blob-Fee-Led Pricing Regime (Original EIP-4844)",
          "description": "When the blob fee is at or above the reserve price, the standard EIP-4844 excess blob gas update rule applies, allowing both increases and decreases based on whether usage exceeds or falls below target.",
          "trigger": "BLOB_BASE_COST * parent.base_fee_per_gas <= GAS_PER_BLOB * get_base_fee_per_blob_gas(parent)",
          "from_state": "excess_blob_gas where blob fee >= reserve price",
          "to_state": "excess_blob_gas += blob_gas_used - target_blob_gas"
        }
      ],
      "dependencies": [
        {
          "id": "DEP-003",
          "symbol": "GAS_PER_BLOB",
          "source": "EIP-4844",
          "value": "2**17 (131072)",
          "description": "The amount of blob gas consumed per blob."
        },
        {
          "id": "DEP-004",
          "symbol": "blobSchedule.target",
          "source": "EIP-7840",
          "description": "The target number of blobs per block, used to compute target_blob_gas."
        },
        {
          "id": "DEP-005",
          "symbol": "blobSchedule.max",
          "source": "EIP-7840",
          "description": "The maximum number of blobs per block, used in the execution-fee-led update formula."
        },
        {
          "id": "DEP-006",
          "symbol": "blobSchedule.baseFeeUpdateFraction",
          "source": "EIP-7840",
          "description": "Used by fake_exponential() inside get_base_fee_per_blob_gas(). The new value must be used immediately after a fork."
        },
        {
          "id": "DEP-007",
          "symbol": "get_base_fee_per_blob_gas",
          "source": "EIP-4844",
          "description": "Computes the blob base fee from the parent header using fake_exponential(). Must use the current blobSchedule.baseFeeUpdateFraction."
        }
      ]
    },
    {
      "id": "SG-003",
      "name": "Fee-Inelasticity and Reserve Price Economics",
      "description": "Describes the economic rationale for the reserve price mechanism. When execution costs dominate blob costs, the demand curve for blobspace becomes inelastic (vertical), and the blob base fee mechanism loses its ability to control equilibrium quantity. The reserve price prevents the blob base fee from falling to 1 wei and restores the price signal function of the mechanism.",
      "invariants": [
        {
          "id": "INV-006",
          "text": "The reserve blob base fee is BLOB_BASE_COST * base_fee_per_gas / GAS_PER_BLOB, maintaining a fixed ratio to execution costs.",
          "formal": "reserve_blob_base_fee = BLOB_BASE_COST * base_fee_per_gas / GAS_PER_BLOB"
        },
        {
          "id": "INV-007",
          "text": "The blob fee's share of total price (blob_fee + execution_cost) is always at least BLOB_BASE_COST / (BLOB_BASE_COST + execution_cost) when the reserve is active.",
          "formal": "blob_fee_share >= BLOB_BASE_COST / (BLOB_BASE_COST + execution_cost)"
        }
      ],
      "functions": [],
      "state_variables": [],
      "preconditions": [],
      "postconditions": [],
      "economic_properties": [
        {
          "id": "ECON-001",
          "name": "Demand Inelasticity Horizon",
          "description": "When execution costs c > 0, the demand curve Q(b + c) has an inelasticity horizon: as b -> 0, Q(b + c) -> Q(c). The demand curve becomes vertical and changes in b no longer affect demand Q.",
          "formal": "lim(b -> 0) Q(b + c) = Q(c) where c = execution_cost * base_fee_per_gas / GAS_PER_BLOB"
        },
        {
          "id": "ECON-002",
          "name": "Price Signal Restoration",
          "description": "The reserve price ensures the blob base fee remains a significant fraction of the total cost, allowing the fee update mechanism to converge on equilibrium in a timely manner rather than spiraling to 1 wei."
        },
        {
          "id": "ECON-003",
          "name": "Equilibrium Formation",
          "description": "The equilibrium must form on the edge of the upper-left quadrant, at the intersection between the target supply curve and demand, or along the reserve price curve. The protocol avoids first-price auction fallback which is considered worse UX."
        }
      ]
    },
    {
      "id": "SG-004",
      "name": "KZG Proof Verification Cost Justification",
      "description": "Provides the computational justification for requiring blob consumers to pay a minimum fee that reflects the compute cost imposed on nodes. KZG proof verification for blobs is computationally expensive, and the reserve price ensures consumers pay at least a relevant fraction of the market rate for node compute.",
      "invariants": [
        {
          "id": "INV-008",
          "text": "BLOB_BASE_COST is set relatively moderately compared to the actual compute costs that blobs impose on nodes (KZG proof verification costs approximately 15x a single point evaluation)."
        }
      ],
      "functions": [],
      "state_variables": [],
      "preconditions": [],
      "postconditions": [],
      "compute_cost_analysis": [
        {
          "id": "CC-001",
          "context": "EL Mempool Verification",
          "description": "EL nodes batch-verify CELLS_PER_EXT_BLOB (128) cell proofs per blob before including a tx in their tx pool. This is roughly 15x more expensive than a single POINT_EVALUATION_PRECOMPILE_GAS operation.",
          "relative_cost": "15x point evaluation"
        },
        {
          "id": "CC-002",
          "context": "Full Node Column Custody",
          "description": "Full nodes verify 4 custodied columns, each containing one cell from all blobs in the payload. Column cell proofs can be batch-verified.",
          "columns": 4
        },
        {
          "id": "CC-003",
          "context": "Supernode Column Custody",
          "description": "Supernodes verify 128 custodied columns, each containing one cell from all blobs in the payload.",
          "columns": 128
        },
        {
          "id": "CC-004",
          "context": "Peer Sampling",
          "description": "Nodes peer-sample SAMPLES_PER_SLOT (8) columns each slot in addition to custodied columns.",
          "samples_per_slot": 8
        }
      ],
      "dependencies": [
        {
          "id": "DEP-008",
          "symbol": "POINT_EVALUATION_PRECOMPILE_GAS",
          "source": "EIP-4844",
          "value": 50000,
          "description": "Gas charged for a single point evaluation KZG proof verification via the precompile."
        },
        {
          "id": "DEP-009",
          "symbol": "CELLS_PER_EXT_BLOB",
          "source": "EIP-7594",
          "value": 128,
          "description": "Number of cell proofs that must be verified per blob in PeerDAS."
        }
      ]
    },
    {
      "id": "SG-005",
      "name": "Fork Transition Handling",
      "description": "Specifies the critical requirement that during the first block after a fork, the new blobSchedule parameters must be used immediately. This includes using the new baseFeeUpdateFraction in fake_exponential() when computing base_fee_per_blob_gas, and the new max and target values in calc_excess_blob_gas().",
      "invariants": [
        {
          "id": "INV-009",
          "text": "In the first block after a fork, fake_exponential() must use the new blobSchedule.baseFeeUpdateFraction when calculating base_fee_per_blob_gas via get_base_fee_per_blob_gas(parent).",
          "formal": "fake_exponential_fraction == new_blobSchedule.baseFeeUpdateFraction"
        },
        {
          "id": "INV-010",
          "text": "In the first block after a fork, the new blobSchedule.max and blobSchedule.target must be used in calc_excess_blob_gas().",
          "formal": "blobSchedule.max == new_fork_max AND blobSchedule.target == new_fork_target"
        }
      ],
      "functions": [],
      "state_variables": [],
      "preconditions": [
        {
          "id": "PRE-003",
          "text": "The current block's blobSchedule must be resolved before calling calc_excess_blob_gas() or get_base_fee_per_blob_gas()."
        }
      ],
      "postconditions": [],
      "state_transitions": [
        {
          "id": "ST-004",
          "name": "Fork Transition",
          "description": "On the first block of a new fork, all blobSchedule parameters (target, max, baseFeeUpdateFraction) switch to the new fork's values. This is a discrete transition that affects both the reserve price comparison and the excess blob gas computation.",
          "trigger": "Block is first block of new fork",
          "from_state": "Old fork blobSchedule parameters",
          "to_state": "New fork blobSchedule parameters"
        }
      ]
    },
    {
      "id": "SG-006",
      "name": "Delayed Response and Fee Convergence",
      "description": "Describes the behavior during the execution-fee-led pricing regime where the blob base fee rises smoothly toward the reserve price without allowing decreases. When the execution base fee rises quickly, there may be a few blocks of lag before the blob base fee catches up, during which target_blob_gas is never subtracted.",
      "invariants": [
        {
          "id": "INV-011",
          "text": "In the execution-fee-led regime, the blob base fee can only increase, never decrease, since target_blob_gas is not subtracted.",
          "formal": "if reserve_price_active then excess_blob_gas(n+1) >= excess_blob_gas(n) for any non-zero blob_gas_used"
        },
        {
          "id": "INV-012",
          "text": "The maximum per-block increase in excess_blob_gas is preserved regardless of pricing regime, ensuring no sudden fee spikes.",
          "formal": "delta_excess_blob_gas <= GAS_PER_BLOB * blobSchedule.max * (blobSchedule.max - blobSchedule.target) // blobSchedule.max"
        }
      ],
      "functions": [],
      "state_variables": [],
      "preconditions": [],
      "postconditions": [],
      "behavioral_properties": [
        {
          "id": "BP-001",
          "name": "Monotonic Fee Increase in Reserve Regime",
          "description": "When in the execution-fee-led regime, the blob base fee increases monotonically with each block that contains blobs, providing smooth convergence toward the reserve price."
        },
        {
          "id": "BP-002",
          "name": "Bounded Convergence Lag",
          "description": "If the execution base fee rises quickly, there may be a temporary lag of a few blocks before the blob base fee catches up. During this period, the blob fee increases without any possibility of decrease."
        },
        {
          "id": "BP-003",
          "name": "Spike Prevention",
          "description": "Unlike the current mechanism where the blob base fee can fall to 1 wei and then require over an hour of near-full blocks to restore equilibrium, the reserve price prevents such dramatic drops and the resulting spiky resource consumption."
        }
      ]
    },
    {
      "id": "SG-007",
      "name": "Future Scalability Design",
      "description": "Addresses the long-term sustainability of the reserve price as Ethereum scales. Because the reserve price is defined relative to the execution base fee rather than as a fixed absolute value, it naturally adjusts as both blobspace and blockspace scale. However, if blob throughput scales significantly faster than execution throughput, the reserve price could become relatively too high.",
      "invariants": [
        {
          "id": "INV-013",
          "text": "If Ethereum scales blockspace and blobspace roughly in synchrony, the reserve price remains at the desired level without requiring parameter changes.",
          "formal": "if scale(blobspace) ~ scale(blockspace) then BLOB_BASE_COST remains appropriate"
        }
      ],
      "functions": [],
      "state_variables": [],
      "preconditions": [],
      "postconditions": [],
      "scalability_analysis": [
        {
          "id": "SCALE-001",
          "name": "Revenue Share Bound",
          "description": "At 1000 blobs and 30M execution gas per block, Ethereum would derive approximately 21.5% of income from blob gas even at the reserve price, suggesting BLOB_BASE_COST would be too high at that scale.",
          "scenario": "1000 blobs, 30M execution gas",
          "blob_revenue_share": "21.5%"
        },
        {
          "id": "SCALE-002",
          "name": "No Fixed Threshold Needed",
          "description": "Because the reserve price is proportional to the execution base fee rather than a fixed wei amount, it automatically adjusts with technological progress (Moore's law, Nielsen's law) without requiring governance intervention."
        }
      ]
    }
  ],
  "security_considerations": [
    {
      "id": "SEC-001",
      "text": "The blob base fee will settle at a level where a blob costs at least BLOB_BASE_COST execution gas. To the best of the authors' knowledge, there are no security risks associated with this.",
      "risk_level": "none_identified",
      "mitigation": "The mechanism is a simple if-clause addition to an existing function with well-understood behavior."
    }
  ],
  "cross_references": [
    {
      "eip": 4844,
      "relationship": "modifies",
      "description": "EIP-7918 modifies the calc_excess_blob_gas() function originally defined in EIP-4844 by adding a reserve price check."
    },
    {
      "eip": 7840,
      "relationship": "depends_on",
      "description": "EIP-7918 uses the blobSchedule (target, max, baseFeeUpdateFraction) introduced in EIP-7840."
    },
    {
      "eip": 7594,
      "relationship": "references",
      "description": "EIP-7918 references EIP-7594 (PeerDAS) for KZG proof verification cost analysis context."
    }
  ],
