{
  "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7934.md",
  "title": "EIP-7934: RLP Execution Block Size Limit",
  "eip_metadata": {
    "eip": 7934,
    "status": "Final",
    "type": "Standards Track",
    "category": "Core",
    "created": "2025-04-16",
    "requires": [],
    "authors": [
      "Giulio Rebuffo (@Giulio2002)",
      "Ben Adams (@benaadams)",
      "Storm Slivkoff (@sslivkoff)"
    ]
  },
  "sub_graphs": [
    {
      "id": "SG-001",
      "name": "Block Size Constants Definition",
      "description": "Defines the protocol-level constants that govern the maximum allowed RLP-encoded execution block size. MAX_BLOCK_SIZE (10 MiB) is the absolute upper bound aligned with the CL gossip protocol limit. SAFETY_MARGIN (2 MiB) reserves space for beacon block overhead. MAX_RLP_BLOCK_SIZE is the effective limit applied to RLP-encoded execution blocks, computed as MAX_BLOCK_SIZE - SAFETY_MARGIN.",
      "invariants": [
        {
          "id": "INV-001",
          "text": "MAX_BLOCK_SIZE must equal 10,485,760 bytes (10 MiB).",
          "formal": "MAX_BLOCK_SIZE == 10_485_760"
        },
        {
          "id": "INV-002",
          "text": "SAFETY_MARGIN must equal 2,097,152 bytes (2 MiB).",
          "formal": "SAFETY_MARGIN == 2_097_152"
        },
        {
          "id": "INV-003",
          "text": "MAX_RLP_BLOCK_SIZE must equal MAX_BLOCK_SIZE minus SAFETY_MARGIN, i.e. 8,388,608 bytes (8 MiB).",
          "formal": "MAX_RLP_BLOCK_SIZE == MAX_BLOCK_SIZE - SAFETY_MARGIN == 8_388_608"
        },
        {
          "id": "INV-004",
          "text": "The relationship between the three constants is fixed and deterministic: MAX_RLP_BLOCK_SIZE is always derived from the other two.",
          "formal": "MAX_RLP_BLOCK_SIZE == MAX_BLOCK_SIZE - SAFETY_MARGIN"
        }
      ],
      "constants": [
        {
          "id": "CONST-001",
          "name": "MAX_BLOCK_SIZE",
